(()=>{var r=window.__goatcounterSite;if(r){let a=async t=>{let n=t.getAttribute("data-goatcounter-path");if(n)try{let o=await fetch(`${r}/counter/${encodeURIComponent(n)}.json`);if(!o.ok)return;let e=await o.json();(typeof e?.count=="string"||typeof e?.count=="number")&&(t.textContent=String(e.count))}catch(o){console.warn("Failed to load GoatCounter count",o)}};document.querySelectorAll(".goatcounter-views").forEach(t=>{a(t)})}})();
